import { StyleSheet } from 'react-native';

const styles = StyleSheet.create({
    container: {
        height: 30,
        paddingHorizontal: 10,
        borderRadius: 10,
        marginHorizontal: 6,
        alignItems: 'center',
        justifyContent: 'center'
    },

    input: {
        textAlign: 'center',
        minHeight: '%100',
        width: '100%',
        fontSize: 17,
        borderColor: 'gray',
        borderWidth: 2,
        backgroundColor: '#333',
        borderRadius: 10,
        color: '#fff',
    },

    button: {
        paddingHorizontal: 4
    }
});
export { styles };
